#!/usr/bin/env python3
"""Recreate fixtures/ and verifiers/ byte-for-byte.

Both trees are generated rather than committed as loose files so the whole tool
is one directory. Contents are base64 and written in BINARY mode: the fixture
contains binary and unicode files and the MUTATE_BYTE case depends on exact
bytes, so a text-mode round trip would silently change what is being tampered
with and invalidate the committed report hash.

EMPTY_DIRS is recreated explicitly. os.walk yields no files for an empty
directory, so a generator that only walks files silently drops them -- which
has changed a committed report hash before without failing a single test.

    python3 make_fixtures.py [dest]
"""
import base64
import os
import sys

EMPTY_DIRS = [
 "fixtures/valid_bundle/empty_dir"
]

FILES = {
 "fixtures/valid_bundle/binary.dat": "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8gISIjJCUmJygpKissLS4vMDEyMzQ1Njc4OTo7PD0+Pw==",
 "fixtures/valid_bundle/config.json": "ewogICJjb3VudCI6IDMsCiAgIm5hbWUiOiAid2lkZ2V0Igp9Cg==",
 "fixtures/valid_bundle/data.txt": "aGVsbG8gZnJvbSBkYXRhIGZpbGUK",
 "fixtures/valid_bundle/manifest.json": "",
 "fixtures/valid_bundle/nested/more.txt": "bmVzdGVkIGNvbnRlbnQK",
 "fixtures/valid_bundle/notes.txt": "U29tZSBub3RlcyB0aGF0IGFyZSByZWFzb25hYmx5IGxvbmcgc28gdHJ1bmNhdGlvbiBpcyBtZWFuaW5nZnVsIGFuZCBvYnNlcnZhYmxlIGluIHRlc3RzLgo=",
 "fixtures/valid_bundle/unicode.txt": "aMOpbGxvIHfDtnJsZCDigJQg5pel5pys6KqeIGVtb2ppOiDwn46JCg==",
 "verifiers/always_reject_verifier.py": "",
 "verifiers/bundleverify.py": "",
 "verifiers/crashing_verifier.py": "",
 "verifiers/exit2_verifier.py": "",
 "verifiers/flaky_verifier.py": "",
 "verifiers/slow_verifier.py": "",
 "verifiers/uncaught_crash_verifier.py": "",
 "verifiers/weak_verifier.py": ""
}


def main():
    dest = sys.argv[1] if len(sys.argv) > 1 else "."
    for rel in sorted(EMPTY_DIRS):
        os.makedirs(os.path.join(dest, *rel.split("/")), exist_ok=True)
    for rel in sorted(FILES):
        path = os.path.join(dest, *rel.split("/"))
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(base64.b64decode(FILES[rel]))
    print("wrote %d files, %d empty dirs to %s" % (len(FILES), len(EMPTY_DIRS), dest))
    return 0


if __name__ == "__main__":
    sys.exit(main())
